import{_ as u,a0 as a,w as r,s,I as i,x as t,a1 as l,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀 | LCTT x X-CMD","titleTemplate":false,"description":"Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking","title":"Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀","tag":"201311","desc":""},"relativePath":"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking.md","filePath":"[post].md"}'),d={name:"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking.md"};function x(m,n,C,b,M,v){const e=a("Link");return r(),s("div",null,[n[14]||(n[14]=i("h1",{id:"canonical-dev稱linux-mint-脆弱-不要將其用於網銀",tabindex:"-1"},[t("Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀 "),i("a",{class:"header-anchor",href:"#canonical-dev稱linux-mint-脆弱-不要將其用於網銀","aria-label":"Permalink to “Canonical Dev稱Linux Mint“脆弱”，不要將其用於網銀”"},"​")],-1)),i("p",null,[i("strong",null,[n[1]||(n[1]=t("一位Canonical公司",-1)),l(e,{href:"https://lists.ubuntu.com/archives/ubuntu-devel-discuss/2013-November/014770.html"},{default:o(()=>[...n[0]||(n[0]=[t("工程師建議",-1)])]),_:1}),n[2]||(n[2]=t("：基於Ubuntu的流行操作系統Linux Mint用户不應該將其用於網銀 。",-1))])]),n[15]||(n[15]=p("<p>Mint決定禁止更新那些存在已知安全問題的安裝包 - 從內核、瀏覽器到啓動加載器和Xorg顯示服務 - 這樣給用户帶來了一個“脆弱的系統” ，Oliver Grawert説。</p><blockquote><p>“不去馬上整合Ubuntu提交的那些修正，而是拒絕這些軟件包的（安全）更新。我要説，強制保持一個有缺陷的內核、瀏覽器或xorg，而不是允許安裝更新補丁，這會變成一個易受攻擊的系統，（原文如此）”。</p><p>“就我個人而言，我不會用它做網銀操作。”</p></blockquote><p>當然不只有Grawert認為Mint在安全意識上的低下。Mozilla貢獻者兼前Ubuntu成員 <strong>Benjamin Kerensa</strong> 也有同樣的看法：</p><blockquote><p>“目前還不清楚為什麼Linux Mint禁止所有的安全更新。我可以説，Mint需要花好幾個月才能得到一個Firefox的修正版，而Ubuntu和Debian已經早在他們的包上打了安全補丁。</p><p>這將置Linux Mint用户處於危險中，也是我從來不建議任何人將Linux Mint作為一種替代Ubuntu的系統的主要原因之一。”</p></blockquote><p>Oliver Grawert是一位可靠的撰稿人。作為一位Canonical公司下的Ubuntu工程師，他比大多數人更瞭解自己在説什麼。</p><p>那麼Mint的用户存在實際風險麼？</p><p>半對半錯。Mint開發商堅決拒絕更新的現有軟件包中大部分的安全“漏洞”（這個詞更好一些）都是有記錄和已知的，雖然這些漏洞很少被利用。因此對用户構成的“實際風險”仍然存在，至少現在，在理論上是很有可能的。</p><p>也就是説，沒有發生<strong>已知的</strong>由於使用Mint發行版（或任何其他基於Ubuntu的未打補丁的發行版）並被通過利用Grawert引用的Ubuntu開發郵件列表上的漏洞造成身份盜竊乃至更糟的事故的情況。</p><p>但是，僅僅因為迄今為止沒有人曾經鑽進這扇半掩的窗户，並不能説明其他人永遠不會這麼做。</p><p><strong>看到Ubuntu持續被提及有關自身的（主要是理論上）隱私問題後，至少它還穿着另外一隻鞋子，我們可喜的看到它對用户安全的強烈關注正在延伸至其他發行版上。</strong></p><p><em>請注意：我們已經向Linux Mint徵求意見及澄清，答覆將在後繼文章發表。</em></p><hr>",12)),i("p",null,[n[4]||(n[4]=t("via: ",-1)),l(e,{href:"http://www.omgubuntu.co.uk/2013/11/canonical-dev-dont-use-linux-mint-online-banking-unsecure"},{default:o(()=>[...n[3]||(n[3]=[t("http://www.omgubuntu.co.uk/2013/11/canonical-dev-dont-use-linux-mint-online-banking-unsecure",-1)])]),_:1})]),i("p",null,[n[7]||(n[7]=t("譯者：",-1)),l(e,{href:"https://github.com/whatever1992"},{default:o(()=>[...n[5]||(n[5]=[t("whatever1992",-1)])]),_:1}),n[8]||(n[8]=t(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原創翻譯，",-1)),l(e,{href:"http://linux.cn/"},{default:o(()=>[...n[10]||(n[10]=[t("Linux中國",-1)])]),_:1}),n[13]||(n[13]=t(" 榮譽推出",-1))])])}const T=u(d,[["render",x]]);export{f as __pageData,T as default};
